#include <stdio.h>

 


int   main() {
    int a = 0; 
    int b = 1;  
    int c = 0; 
    char c = 'A'; 
    int c = 0; 
    char d = '\n'; 
    char e = '\\'; 
    char f = '\''; 
    char g = '\"'; 

    printf("Hola mundo\n"); 
    printf("Esto no es comentario: // ni esto /* comentario */\n");
    printf("Secuencias: \\n \\\\ \\\" \\\'\n");

    
    a = a + b;   b = a - b; 
     
    a++; 

    
    printf("/ no es comentario\n");
    printf("* tampoco es comentario\n");
    printf("/x tampoco\n");
    printf("/ "); 

    
    return 0; 
}

 








int dummy_function() {
    int x = 0;
    x++; 
     
    printf("Cadena con comillas: \"texto\" y barra \\\n");
    printf("/* esto parece comentario pero no lo es */\n");
    printf("// tampoco es comentario\n");
    char ch = '/'; 
    char ch2 = '*'; 
    char ch3 = '\''; 
    char ch4 = '\"'; 
    return x;
}



 


